#include <stdio.h>

int main(void) {
    int n;
    if (scanf("%d", &n) != 1) return 0;

    int a[100];
    int mn = 101, mx = 0;

    for (int i = 0; i < n; i++) {
        scanf("%d", &a[i]);
        if (a[i] < mn) mn = a[i];
        if (a[i] > mx) mx = a[i];
    }

    int answer = 0;

    for (int h = mn; h < mx; h++) {
        int in_component = 0;

        for (int i = 0; i < n; i++) {
            if (a[i] <= h) {
                if (!in_component) {
                    answer++;
                    in_component = 1;
                }
            } else {
                in_component = 0;
            }
        }
    }

    printf("%d\n", answer);
    return 0;
}
